#include <bits/stdc++.h>
#define int long long 
using namespace std;

signed main() {
	// your code goes here
	
	int t; cin >> t;
	while (t--)
	{
	    int n; cin >> n;
	    vector<int>a(3*n+1);
	    
	    
	    int m= 3*n;
	    
	    for (int i=1;i<=m;i++) cin >> a[i];
	    
	    sort(a.begin()+1,a.end(),greater<int>());
	    vector<int>p(m+1,0);
	    
	    for (int i=1;i<=m;i++) p[i]=p[i-1]+a[i];
	    
	    int ans =0;
	    
	    for (int i=0;i<=n;i++)
	    {
	        int l=0; int r=n-i;
	        
	        while (r-l>2)
	        {
	            int left = l+(r-l)/3;
	            int right = r-(r-l)/3;
	            
	            
	           int ff = 2LL*p[i]+p[i+2*left] + 3LL*p[m-2*i-left];
	           int gg = 2LL*p[i]+p[i+2*right]+3LL*p[m-2*i-right];
	           
	           if (ff<gg)
	           {
	               l=left;
	               
	           }
	           else r=right;
	        }
	           for (int j=l;j<=r;j++)
	           {
	               int x =2LL*p[i]+p[i+2*j]+3LL*p[m-2*i-j];
	               ans =max(ans,x);
	           }
	        
	        
	        
	    }
	    
	    cout << ans << endl;
	    
	    
	    
	    
	}

}
